new file mode 100644
@@ -0,0 +1,33 @@
+package com.ihoment.pojo.constant.shopify;
+
+import org.apache.commons.lang3.StringUtils;
+
+/**
+ * Shopify 礼品卡同步模式（v2）
+ *
+ * @author lrw
+ */
+public enum ShopifyGiftCardSyncModeEnum {
+
+    /** 默认：有更新时间游标则增量，否则全量 */
+    INCREMENTAL,
+
+    /** 强制全量（UPDATED_AT 倒序 + 页游标续跑） */
+    BOOTSTRAP;
+
+    /**
+     * 解析同步模式，空或非法时默认 INCREMENTAL
+     *
+     * @param mode 模式字符串：INCREMENTAL / BOOTSTRAP
+     * @return 枚举
+     */
+    public static ShopifyGiftCardSyncModeEnum from(String mode) {
+        if (StringUtils.isBlank(mode)) {
+            return INCREMENTAL;
+        }
+        if ("BOOTSTRAP".equalsIgnoreCase(mode.trim())) {
+            return BOOTSTRAP;
+        }
+        return INCREMENTAL;
+    }
+}

