+package com.ihoment.command.shopify.dashboard;
+
+import com.ihoment.pojo.constant.shopify.dashboard.ShopifyDashboardCommandEnum;
+import org.springframework.stereotype.Component;
+
+import java.util.HashMap;
+import java.util.Map;
+
+/** 经营看板：汇总 MCF 加急配送订单数（店铺/国家快照 prime_orders） */
+@Component
+public class ShopifyDashboardPrimeOrdersCommand implements ShopifyDashboardCommand<Integer> {
+
+    @Override
+    public Map<String, Integer> calculate(ShopifyDashboardCalcContext ctx) {
+        int sum = ctx.getDtoList().stream().mapToInt(d -> d.getPrimeOrders() == null ? 0 : d.getPrimeOrders()).sum();
+        Map<String, Integer> resultMap = new HashMap<>();
+        resultMap.put(getCommandEnum().getName(), sum);
+        return resultMap;
+    }
+
+    @Override
+    public ShopifyDashboardCommandEnum getCommandEnum() {
+        return ShopifyDashboardCommandEnum.PRIME_ORDERS;
+    }
+}

