+                    sellIn = MathUtil.add(sellIn, weekData.getAdjustShippingAdviceCruiser());
+                    sellIn = MathUtil.add(sellIn, weekData.getAdjustShippingAdviceAir());
+                    sellIn = MathUtil.add(sellIn, weekData.getAdjustShippingAdviceSlowShip());
+                    sellIn = MathUtil.add(sellIn, weekData.getAdjustShippingAdviceShipThirdParty());
+                    weekMap.put(weekData.getWeek(), sellIn);
+                }
+                result.put(vo.getListingId(), weekMap);

