+        if (StrUtil.isBlank(json)) {
+            return new ShipBoardExtendedLogisticsDataDTO();
+        }
+        try {
+            ShipBoardExtendedLogisticsDataDTO result =
+                    JSON.parseObject(json, ShipBoardExtendedLogisticsDataDTO.class);
+            if (result == null) {
+                throw new BusinessException(buildInvalidJsonMessage(shipBoardSubId));
+            }
+            result.normalize();
+            if (!Integer.valueOf(CURRENT_VERSION).equals(result.getVersion())) {
+                throw new BusinessException("发运看板扩展物流指标版本不支持"
+                        + buildSubIdSuffix(shipBoardSubId) + "，version=" + result.getVersion());
+            }
+            return result;
+        } catch (BusinessException e) {
+            throw e;
+        } catch (Exception e) {
+            throw new BusinessException(buildInvalidJsonMessage(shipBoardSubId), e);
+        }
